type SVGProps = Record<string, string>;
/**
 * A Lucide icon node (an svgson-like internal format)
 */
type LucideIconNode = [attrName: string, attributes: SVGProps] | [attrName: string, attributes: SVGProps, children: LucideIconNode[]];
/**
 * A Lucide icon object that fully describes an icon to be displayed.
 */
type LucideIconData = {
    name: string;
    node: LucideIconNode[];
    aliases?: string[];
} & ({
    size: number;
} | {
    width: number;
    height: number;
});

